  "执行中...": "実行中...",
  "主日志新增自动轮转与历史清理：当天日志超过 20MB 时，下次启动自动滚动为 .1 备份、新日志从零开始，日志风暴时磁盘占用封顶；同时启动时自动清理 7 天前的 tunhook-*.log 历史日志（含 .1），避免长期运行日志无限增长写满 fnOS 系统分区（此前 busy-loop 期间曾刷出单日 90MB+ 且永久堆积）。仅在启动时执行，无任何后台开销": "メインログに自動ローテーションと履歴クリーンアップを追加：当日のログが 20MB を超えると、次回起動時に .1 バックアップへローテーションし、新しいログはゼロから開始します。ログ急増時もディスク使用量に上限が設けられます。また起動時に 7 日より前の tunhook-*.log 履歴（.1 を含む）を自動削除し、長期運用でログが無限に増えて fnOS のシステムパーティションを圧迫するのを防ぎます（従来はビジーループ時に 1 日で 90MB 以上を出力し、それが永久に蓄積していました）。実行は起動時のみで、バックグラウンドのオーバーヘッドはありません",
  "自动（所有网卡 0.0.0.0）": "自動（すべてのネットワークインターフェース 0.0.0.0）",
  "DNS 账户用于 ACME 证书的通配符（*.example.com）DNS-01 验证：申请时自动添加 TXT 解析记录，验证后自动删除": "DNS アカウントは ACME 証明書のワイルドカード（*.example.com）DNS-01 認証に使用します。申請時に TXT レコードを自動追加し、認証後に自動削除します",
  "DNS 账户用于 ACME 证书的通配符（*.example.com）DNS-01 验证：申请时自动添加 TXT 解析记录，验证后自动删除。": "DNS アカウントは ACME 証明書のワイルドカード（*.example.com）DNS-01 認証に使用します。申請時に TXT レコードを自動追加し、認証後に自動削除します。",
  "DNS-01 适用于通配符域名（*.example.com）或 80 端口不可达场景；选择后通过 DNS 服务商 API 自动添加 TXT 记录验证": "DNS-01 はワイルドカードドメイン（*.example.com）や 80 番ポートに到達できない場合に適しています。選択すると DNS プロバイダーの API 経由で TXT レコードを自動追加して認証します",
  "frp 客户端全局日志级别（log.level），运行日志可在 FRP服务器 页面查看。": "frp クライアントのグローバルログレベル（log.level）。実行ログは FRP サーバーページで確認できます。",
