  "安装": "インストール",
  "安装/升级时检测并复用上一版本数据，防止新建覆盖：安装与升级预处理检查数据目录（@appdata/TunHook）与配置目录（@appconf/TunHook）是否已有数据，齐全则直接复用，部分缺失只补迁移缺失项，迁移目标已存在则跳过，绝不新建默认数据覆盖已有数据": "インストール/アップグレード時に前バージョンのデータを検出して再利用し、新規作成による上書きを防止します。インストールとアップグレードの前処理で、データディレクトリ（@appdata/TunHook）と設定ディレクトリ（@appconf/TunHook）に既存データがあるかを確認します。揃っていればそのまま再利用し、一部欠けている場合は不足分のみ移行します。移行先が既に存在する場合はスキップし、既定データを新規作成して既存データを上書きすることは決してありません",
  "安装覆盖与升级共用同一套旧数据全位置迁移逻辑，覆盖安装同样不丢数据；修复卸载「保留数据」时数据库备份/恢复路径（数据库位于 @appdata/db/ 子目录）": "上書きインストールとアップグレードは同じ旧データ全位置移行ロジックを共用するため、上書きインストールでもデータは失われません。アンインストール時の「データを保持」におけるデータベースのバックアップ/復元パスを修正しました（データベースは @appdata/db/ サブディレクトリにあります）",
