  "保存失败：": "保存に失敗しました：",
  "保存通道后按需补写解析记录：只写该通道实际用到的那条主机记录，已解析到目标的跳过、同名同值跳过，同名不同值绝不覆盖（只回报冲突）；删除通道 / 代理时按值匹配清理，只删「主机记录 + 类型 + 值」三者都对得上的那一条，手工改过的记录不误删": "トンネル保存後、必要に応じて DNS レコードを補記します。そのトンネルが実際に使用するホストレコードのみを書き込み、既にターゲットに解決されているものはスキップし、同名同値もスキップします。同名で値が異なる場合は決して上書きせず、競合のみを報告します。トンネル / プロキシの削除時は値の一致でクリーンアップし、「ホストレコード + タイプ + 値」の 3 つがすべて一致する 1 件のみを削除するため、手動で変更したレコードを誤って削除しません",
