  "备案": "ICP 登録",
  "备份/恢复覆盖全部内容模块：新增证书库与 ACME 联系人、地理数据源与已下载 IP 段（含 36 万级数据）、图标与桌面图标、Webhook 通道记录 4 个模块；导入上限提升至 512MB（容纳全量地理数据）": "バックアップ/復元がすべてのコンテンツモジュールを対象に：証明書ストアと ACME 連絡先、ジオデータソースとダウンロード済み IP 範囲（36 万件規模のデータを含む）、アイコンとデスクトップアイコン、Webhook トンネル記録の 4 モジュールを追加しました。インポート上限を 512MB に引き上げました（地理データ全体を格納可能）",
  "备份会导出系统设置、自定义 UI、转发规则、FRP 服务器与代理、IP 过滤、域名解析等配置；不包含日志与流量历史。": "バックアップには、システム設定、カスタム UI、転送ルール、FRP サーバーとプロキシ、IP フィルタリング、DNS レコードなどの設定が含まれます。ログとトラフィック履歴は含まれません。",
