  "本软件基于以下开源项目构建，全部依赖保持上游官方许可协议，感谢所有作者与开源社区的无私贡献。点击各库条目可展开查看详细说明。": "本ソフトウェアは以下のオープンソースプロジェクトを基に構築されています。すべての依存関係は上流の公式ライセンスを保持しています。作者の皆様とオープンソースコミュニティの惜しみない貢献に感謝します。各ライブラリの項目をクリックすると詳細が展開されます。",
