  "超时": "タイムアウト",
  "超时（秒）": "タイムアウト（秒）",
  "彻底修复 TCP 打洞通道满载 CPU 的根因：除读超时外，公网 STUN 服务器/NAT 主动断开空闲保活连接时，第三方 STUN 库的常驻读循环会因反复读到 EOF/reset 而全速空转（这才是真实环境启动即阵发性满载、而本机难以复现的触发路径）。本版彻底弃用该库的 Client，改在裸连接上手工收发 STUN 事务，空闲时无后台读循环、连接断开即立即重连，从结构上消除忙转": "TCP ホールパンチングトンネルが満負荷時に CPU を消費する根本原因を徹底的に修正しました。読み取りタイムアウトに加え、公衆 STUN サーバー/NAT がアイドル状態のキープアライブ接続を能動的に切断した際、サードパーティ製 STUN ライブラリの常駐読み取りループが EOF/reset を繰り返し読み取って全速で空回りします（これこそが実環境で起動直後に断続的な満負荷を引き起こし、ローカルでは再現しにくいトリガー経路です）。本バージョンでは当該ライブラリの Client を完全に廃止し、生の接続上で STUN トランザクションを手動で送受信します。アイドル時はバックグラウンドの読み取りループがなく、接続切断時は即座に再接続するため、ビジー回転を構造的に排除しました。",
  "成功": "成功",
  "持续强化 ROOT 版专属能力（桌面图标一键打包安装、Docker端口扫描、服务器连通性测试）": "ROOT 版専用機能を継続的に強化（デスクトップアイコンのワンクリックパッケージとインストール、Docker ポートスキャン、サーバー接続性テスト）",
