  "端口扫描": "ポートスキャン",
  "端口扫描新增 Docker 扫描模式与局域网自定义范围（CIDR/单IP/起止IP，支持 IPv6）；隧道/代理列表新增当前连接数与运行状态显示": "ポートスキャンに Docker スキャンモードと LAN のカスタム範囲（CIDR／単一 IP／開始〜終了 IP、IPv6 対応）を追加。トンネル／プロキシ一覧に現在の接続数と稼働状態を表示",
  "端口扫描新增域名目标：输入域名后自动解析 IPv4 地址，仅解析出一个地址时直接开始扫描，多个地址时在输入框下方列出全部 IP 由用户选择（点击即按当前动作执行「扫描端口」/「扫描IP」，并可随时切换地址重扫）；新增 /api/ports/resolve 解析接口（多公共 DNS 兜底、地址去重、兼容误粘贴完整 URL）": "ポートスキャンにドメインターゲットを追加しました。ドメインを入力すると IPv4 アドレスを自動解決し、1 つだけ解決できた場合はそのままスキャンを開始します。複数ある場合は入力欄の下にすべての IP を表示してユーザーが選択します（クリックすると現在のアクション「ポートスキャン」／「IP スキャン」を実行し、いつでもアドレスを切り替えて再スキャンできます）。また /api/ports/resolve 解決 API を追加しました（複数の公共 DNS フォールバック、アドレスの重複排除、完全な URL の誤貼り付けにも対応）。",
  "端口扫描增强：隧道创建与转发弹窗内置「扫描端口」入口，结果一键填入": "ポートスキャンの強化：トンネル作成と転送のダイアログに「ポートスキャン」の入口を組み込み、結果をワンクリックで入力できます",
  "端口探测": "ポート検出",
  "端口探测 {0} / {1}": "ポート検出 {0} / {1}",
  "端口探测 {0}:{1}": "ポート検出 {0}:{1}",
  "端口限制锥形": "ポート制限コーン",
  "端口占用自动处理（自动选择 50000-60000 空闲端口）": "ポート競合の自動処理（50000〜60000 の空きポートを自動選択）",
  "端口转发": "ポート転送",
  "端口转发规则与描述": "ポート転送ルールと説明",
  "端口转发通道表单的「绑定域名」同步改造为「域名选择 + 主机记录」（与上一版 MEFrp / LoliaFrp 隧道一致）：域名从「域名解析」模块已有域名中下拉（跨账户聚合、优先展示已解析到所选 Frps 服务器 IP 的域名、未解析的标注「暂未解析」但同样可选），主机记录可选 @（主域名）或子域名（填前缀并实时显示完整域名）；新增「自定义域名」选项，选中后就地变为手动输入完整域名的输入框": "ポート転送トンネルフォームの「ドメイン紐付け」を「ドメイン選択 + ホストレコード」に刷新しました（前バージョンの MEFrp / LoliaFrp トンネルと同様）。ドメインは「DNS レコード」モジュールに既存のドメインから選択し（アカウント横断で集約、選択中の Frps サーバー IP に解決済みのドメインを優先表示、未解決のものは「未解決」と表示しつつ選択可能）、ホストレコードは @（apex ドメイン）またはサブドメイン（プレフィックスを入力すると完全なドメインをリアルタイム表示）から選べます。新たに「カスタムドメイン」オプションを追加し、選択するとその場で完全なドメインを手入力する入力欄に切り替わります。",
