  "更新 Client ID / Client Secret 或回调基址。回调地址需与 LoliaFrp 控制台填写的「重定向 URI」完全一致（含端口）；\n      Client Secret 留空表示沿用已保存的值。当前回调地址：": "Client ID / Client Secret またはコールバックベース URL を更新します。コールバック URL は LoliaFrp コンソールで入力した「リダイレクト URI」と完全に一致させる必要があります（ポートを含む）。\n      Client Secret を空欄にすると保存済みの値が使用されます。現在のコールバック URL：",
