  "公网 IPv6 探测增加地址族校验：出站经 NAT64 时回显服务可能误返回 IPv4，检测到期望 IPv6 得到 IPv4 会自动跳过，保证存储的确实是 IPv6": "公衆 IPv6 検出にアドレスファミリー検証を追加しました。NAT64 経由のアウトバウンドではエコーサービスが誤って IPv4 を返す場合があるため、IPv6 を期待して IPv4 が返された場合は自動的にスキップし、IPv6 アドレスのみを保存します。",
