  "官方内核约 40MB，按需下载（不随 TunHook 安装包内置）；无外网时可先下载离线包再上传。": "公式カーネルは約 40MB で、必要に応じてダウンロードされます（TunHook インストールパッケージには含まれません）。外部ネットワークがない場合は、オフラインパッケージをダウンロードしてからアップロードしてください。",
  "管理": "管理",
  "管理界面": "管理画面",
  "管理控制台移动端排版全面适配：各弹窗多列统计卡与双列表单窄屏自动单列堆叠、弹窗内固定 min-width 窄屏归零，消除横向溢出；STUN 探测弹窗控制行换行；端口扫描模式切换条可换行、DNS 结果表横向滚动；Cloudflare 弹窗固定宽控件改弹性填充；仪表盘弹窗与布局编辑预览降列；「输入框+按钮」操作行统一为放得下就同一行、放不下才折行（桌面端布局全部不变）": "管理コンソールのモバイル向けレイアウトを全面的に調整しました。各モーダルの複数列統計カードと2列フォームは狭い画面で自動的に1列に積み重なり、モーダル内の固定 min-width は狭い画面で 0 になり、横スクロールのオーバーフローを解消します。STUN 検出モーダルの操作行は折り返し可能になり、ポートスキャンのモード切り替えバーは折り返し、DNS 結果テーブルは横スクロールします。Cloudflare モーダルの固定幅コントロールは可変幅に変更し、ダッシュボードのモーダルとレイアウト編集プレビューは列数を減らしました。「入力欄＋ボタン」の操作行は収まる場合は同じ行、収まらない場合のみ折り返すように統一しました（デスクトップのレイアウトはすべて変更ありません）。",
