  "回调地址暂不可用：请先在「Webhook」页开启接收端口（默认 19520）并确保设备 IP/域名可从浏览器访问；也可以在下方手动指定回调基址。": "コールバック URL は現在利用できません。「Webhook」ページで受信ポート（デフォルト 19520）を有効にし、デバイスの IP/ドメインにブラウザからアクセスできることを確認してください。下でコールバックベース URL を手動指定することもできます。",
