  "回调字符": "コールバック文字列",
  "回显服务需返回纯文本 IP 地址。保存后立即重新探测并刷新显示。": "エコーサービスはプレーンテキストの IP アドレスを返す必要があります。保存後すぐに再検出を行い、表示を更新します。",
  "会话超时（毫秒）": "セッションタイムアウト（ミリ秒）",
  "会话空闲超过超时时间后自动回收；超出最大会话数的新来源数据包将被丢弃。": "セッションがタイムアウト時間を超えてアイドル状態になると自動的に回収されます。最大セッション数を超えた新しい送信元のパケットは破棄されます。",
