  "监听端口不变；对外地址按域名 443 展示，需外部反向代理到该端口。": "リッスンポートは変更されません。公開アドレスはドメインの 443 として表示され、外部リバースプロキシからそのポートへ転送する必要があります。",
  "监听端口无效（0-65535）": "リッスンポートが無効です（0-65535）",
  "监听端口以 HTTPS(TLS) 方式监听，自动生成自签名证书，解密后转发到内网 HTTP 服务": "リッスンポートを HTTPS（TLS）で待ち受け、自己署名証明書を自動生成して復号後に内部 HTTP サービスへ転送します",
