  "检测到开启 AutoTLS 的隧道：官方通过定制 frpc 内核在本地自动申请证书，TunHook 内置的官方 frpc 可能无法直接运行该隧道，如启动失败请先关闭 AutoTLS（后续版本将支持 lolia 定制内核）。": "AutoTLS が有効なトンネルを検出しました。公式ではカスタマイズされた frpc カーネルを使用してローカルで証明書を自動取得するため、TunHook 内蔵の公式 frpc ではこのトンネルを直接実行できない場合があります。起動に失敗する場合は、まず AutoTLS を無効にしてください（今後のバージョンで Lolia カスタムカーネルに対応予定です）。",
