  "将清空全部自动记录的被拦截 IP，仅清理历史记录，不影响黑白名单与地区规则。确定清空吗？": "自動記録されたブロック済み IP をすべて消去します。履歴のみを消去し、許可/拒否リストと地域ルールには影響しません。消去しますか？",
  "将清空所有通道与转发的运行/访问历史日志，此操作不可恢复。确定清空吗？": "すべてのトンネルとポート転送の実行/アクセス履歴ログを消去します。この操作は元に戻せません。消去しますか？",
