  "解析记录弹窗无障碍改进：表单标签与输入控件建立真实关联，可点击卡片补齐按钮语义与键盘操作（Enter / 空格）；同步调整仪表盘页头按钮顺序与端口转发图标": "DNS レコードダイアログのアクセシビリティを改善しました。フォームラベルと入力コントロールを正しく関連付け、クリック可能なカードにボタンのセマンティクスとキーボード操作（Enter / スペース）を追加しました。あわせてダッシュボードヘッダーのボタン順序とポート転送アイコンを調整しました。",
  "解析记录清理失败：": "DNS レコードのクリーンアップに失敗しました：",
