  "界面优化：黑白名单地区条目直接展示、网段条目隐藏明文（悬停查看）超 6 条自动滚动；系统设置子菜单重命名（FRP服务器/自定义UI）并调整排序": "UI を改善しました。許可/拒否リストの地域項目はそのまま表示し、CIDR 項目は伏せ字（ホバーで表示）にし、6 件を超えると自動スクロールします。システム設定のサブメニュー名を変更（FRP サーバー / カスタム UI）し、順序も調整しました。",
  "界面与体验优化：响应式布局、键盘焦点可见、尊重系统减少动态效果偏好": "UI と操作性を改善しました。レスポンシブレイアウト、キーボードフォーカスの可視化、システムの「視差効果を減らす」設定への対応を行いました。",
