  "开启后流量先经 TunHook 反代层，读取访客真实 IP；关闭时 frpc 直连本地服务（无法记录访客 IP）。": "有効にすると、トラフィックはまず TunHook のリバースプロキシ層を経由して訪問者の実 IP を取得します。無効にすると frpc がローカルサービスに直接接続します（訪問者 IP は記録できません）。",
