  "连接器内核按需下载（约 40MB 不随安装包内置，带下载进度与离线包上传兜底、原子替换升级不中断隧道）、/ready 连接状态与内核日志查看、随应用启动自启；连接协议默认 HTTP/2（实测大陆链路延迟与吞吐明显优于 QUIC）": "コネクタカーネルは必要に応じてダウンロードされます（約 40MB、インストールパッケージには含まれず、ダウンロード進捗とオフラインパッケージのアップロードによるフォールバック、トンネルを中断しないアトミック置換アップグレードに対応）。/ready による接続状態とカーネルログの確認、アプリ起動時の自動起動に対応します。接続プロトコルはデフォルトで HTTP/2 です（中国本土回線での実測遅延とスループットは QUIC より明らかに優れています）。",
  "连接器尚未拿到临时域名（启动后由 Cloudflare 下发）": "コネクタはまだ一時ドメインを取得していません（起動後に Cloudflare から発行されます）",
