  "两种托管方式：Token 托管（在 Cloudflare 后台建隧道与路由，本页只托管连接器）与 API 全托管（在本页创建隧道、配置域名路由并自动写入 DNS 解析；凭证复用「域名解析」模块的 Cloudflare 账号，账号 ID 由所选域名自动推导）": "2 つのホスティング方式があります。Token ホスティング（Cloudflare ダッシュボードでトンネルとルートを作成し、このページではコネクタのみをホスト）と API 全ホスティング（このページでトンネルを作成し、ドメインルートを設定して DNS レコードを自動書き込み。認証情報は「DNS レコード」モジュールの Cloudflare アカウントを再利用し、アカウント ID は選択したドメインから自動推定）です。",
  "列表「流量统计」列改为当前实时速率（无连接显示 0），frpc 代理新增持久累计流量（无连接不再归零），累计与连接详情在弹窗查看": "一覧の「トラフィック統計」列は現在のリアルタイムレート（接続がない場合は 0）に変更し、frpc プロキシには永続的な累計トラフィックを追加しました（接続がなくても 0 に戻りません）。累計と接続の詳細はモーダルで確認できます。",
  "列表尚未同步到新隧道，请稍后刷新后再启动": "一覧が新しいトンネルにまだ同期されていません。しばらくして更新してから起動してください。",
  "列表为当前活跃的 frpc 转发连接（连接断开后自动消失，已过滤本机回环地址）。访客IP 来自 X-Real-IP / X-Forwarded-For（真实公网 IP）；普通 TCP/UDP 转发链路无法得知访客 IP，显示为 -。累计上下行为该代理的历史累计流量（持久化，无连接时也保留）；下方表格为各连接自建立以来的累计值。": "一覧は現在アクティブな frpc 転送接続です（切断後は自動的に消え、ローカルループバックアドレスは除外されます）。訪問者 IP は X-Real-IP / X-Forwarded-For（実際の公衆 IP）から取得します。通常の TCP/UDP 転送では訪問者 IP を取得できないため「-」と表示されます。累計上り/下りはこのプロキシの過去の累計トラフィック（永続化され、接続がない場合も保持）です。下の表は各接続の確立以降の累計値です。",
