  "每个连接独立映射。连接不同服务器时，NAT会分配不同的外网端口，导致P2P打洞失败。": "接続ごとに個別にマッピングされます。異なるサーバーに接続すると NAT が異なる外部ポートを割り当てるため、P2P ホールパンチが失敗します。",
