  "内核为所有隧道实例共用；各条实例的启动 / 停止 / 日志在下方列表中分别操作。": "コアはすべてのトンネルインスタンスで共有されます。各インスタンスの起動・停止・ログは下のリストで個別に操作します。",
  "内核未安装": "コア未インストール",
  "内核下载前并发测速官方源与 8 个国内加速镜像，按实际吞吐择优并逐源回退；无外网时可上传离线内核包兜底安装": "コアのダウンロード前に、公式ソースと国内の高速ミラー 8 件を同時に速度測定し、実測スループットで最適なものを選び、ソースごとにフォールバックします。外部ネットワークがない場合は、オフラインのコアパッケージをアップロードしてインストールできます",
