  "内网穿透 · 端口转发 · 隧道管理 · 一站式自托管控制台": "リバーストンネリング · ポート転送 · トンネル管理 · オールインワンのセルフホストコンソール",
  "内网地址": "内部アドレス",
  "内置规则": "組み込みルール",
  "能力边界：Cloudflare Tunnel 只发布 HTTP/HTTPS 域名（走 443，无端口号概念），UDP 不支持；\n      TCP/SSH/RDP 类服务需要访问方本地安装 cloudflared 才能连接。\n      需要 TCP/UDP 任意端口映射，请继续用「FRPC」或「MEFrp」。\n      Token 托管与 API 全托管需自有域名并托管在 Cloudflare，且大陆访问通常绕道境外节点，延迟偏高，适合 Webhook 回调与低频网页访问。": "機能の範囲：Cloudflare Tunnel は HTTP/HTTPS ドメインのみを公開し（443 経由、ポート番号の概念なし）、UDP は非対応です。\n      TCP/SSH/RDP 系のサービスに接続するには、アクセス側に cloudflared が必要です。\n      TCP/UDP の任意ポートマッピングが必要な場合は、「FRPC」または「MEFrp」を引き続きご利用ください。\n      Token ホスティングと API 完全ホスティングには、Cloudflare でホストする独自ドメインが必要です。中国本土からのアクセスは通常海外ノードを経由するため遅延が大きく、Webhook コールバックや低頻度の Web アクセスに適しています。",
  "爬虫": "クローラー",
