  "配置探测本机公网 IPv4 / IPv6 地址的方式。默认使用内置 HTTP 请求访问下方的回显服务（无需系统安装 curl）。": "本機のグローバル IPv4 / IPv6 アドレスを検出する方法を設定します。デフォルトでは組み込みの HTTP リクエストで下のエコーサービスにアクセスします（システムに curl は不要です）。",
