  "启用规则": "ルールを有効化",
  "启用后可通过 {0} 访问通道导航页：集中展示已注册通道 / 转发规则 / 代理列表。关闭后 /hook 将无法访问。": "有効化すると {0} でトンネルナビゲーションページにアクセスできます。登録済みのトンネル・転送ルール・プロキシ一覧をまとめて表示します。無効化すると /hook にアクセスできなくなります。",
