  "签发证书": "証明書を発行",
  "前端技术": "フロントエンド技術",
  "前端跨域接口中转，自定义响应头 + 数据透传": "フロントエンドのクロスオリジン API 中継。カスタムレスポンスヘッダーとデータのパススルーに対応",
  "前端轮询统一为「可见性感知」并按下游开销分级：页面不可见时自动暂停、回到前台立即补一次；重接口由 3 秒放宽到 10 秒，其余统一到 5 秒": "フロントエンドのポーリングを「可視性感知」に統一し、下流の負荷で段階化しました。ページが非表示のときは自動停止し、フォアグラウンドに戻ると即座に 1 回更新します。重いエンドポイントは 3 秒から 10 秒に、その他は 5 秒に統一しました",
  "前往": "移動",
  "前往 LoliaFrp 授权": "LoliaFrp の認可へ",
  "前往 MEFrp 官网获取密钥 ↗": "MEFrp 公式サイトでキーを取得 ↗",
  "前往对应模块页": "該当のモジュールページへ",
  "前往系统日志": "システムログへ",
  "前缀": "プレフィックス",
  "浅色": "ライト",
  "浅色主题底色改为无彩中性灰阶 + 纯白表面（参考 PriTime）：页面底 #fafafa、卡片/侧边栏/输入框纯白、内层 #f5f5f5、边框 #e5e5e5；六套配色的浅色底统一为中性底、不再带淡彩染色，层次靠边框与阴影承担，亮环境下更柔和，强调色与深色主题不变": "ライトテーマの背景を無彩色の中性グレー階調＋純白のサーフェスに変更しました（PriTime を参考）：ページ背景 #fafafa、カード/サイドバー/入力欄は純白、内側は #f5f5f5、枠線は #e5e5e5。6 種類の配色のライト背景を統一して中性色とし、淡い色味は付けず、階層は枠線と影で表現します。明るい環境でより柔らかく見え、アクセントカラーとダークテーマは変更ありません",
  "强调色": "アクセントカラー",
  "强制下线": "強制オフライン",
  "切换默认服务器或修改连接池后，已建立的代理会重新连接。": "デフォルトサーバーの切り替えや接続プールの変更後、確立済みのプロキシは再接続されます。",
  "切换主色时自动搭配辅助色；辅助色用于图表第二数据系列、渐变与次级强调。页面背景保持中性，不再随主色换肤。": "プライマリカラーを切り替えるとセカンダリカラーが自動で組み合わされます。セカンダリカラーはグラフの第 2 データ系列、グラデーション、補助的な強調に使用されます。ページ背景は中性のまま維持され、プライマリカラーによるテーマ変更は行いません。",
