  "为 Webhook 代理与端口扫描的自建 HTTP Transport 补齐 TLS 握手超时，避免上游 TLS 握手挂起时拨号 goroutine 长期滞留": "Webhook プロキシとポートスキャンの独自 HTTP Transport に TLS ハンドシェイクのタイムアウトを追加し、上流の TLS ハンドシェイクが停止した際にダイヤルの goroutine が長時間滞留するのを防ぎます",
