  "系统设置 {0} 项": "システム設定 {0} 項目",
  "系统设置侧栏子分区顺序调整，并删除与「系统日志」页重复的「日志管理」分区；把设置页子分区清单提为唯一来源，侧栏子菜单与页头副标题由同一份清单生成（此前两份手工清单已漂移、副标题漏两项）；主侧栏标签顺序调整": "システム設定サイドバーのサブセクション順を調整し、「システムログ」ページと重複していた「ログ管理」セクションを削除しました。設定ページのサブセクション一覧を唯一の情報源とし、サイドバーのサブメニューとページヘッダーのサブタイトルを同じ一覧から生成します（従来の 2 つの手作業リストは乖離し、サブタイトルでは 2 項目が欠けていました）。メインサイドバーのタブ順も調整しました",
  "系统设置分区": "システム設定のセクション",
  "系统设置新增模块管理：可关闭暂不使用的模块（STUN/内网穿透/端口转发/Webhook/MEFrp/Cloudflare Tunnel/端口扫描），关闭后导航入口隐藏、直接访问其页面被拦下、仪表盘对应卡片一并隐藏，已启动的隧道与转发规则照常工作": "システム設定にモジュール管理を追加：未使用のモジュール（STUN/リバーストンネリング/ポート転送/Webhook/MEFrp/Cloudflare Tunnel/ポートスキャン）をオフにできます。オフにするとナビゲーションの入口が非表示になり、そのページへの直接アクセスはブロックされ、ダッシュボードの該当カードも非表示になります。起動中のトンネルと転送ルールは通常どおり動作します",
  "系统自动生成的 Cloudflare 隧道回源转发，请到「Cloudflare Tunnel」页面管理": "システムが自動生成した Cloudflare トンネルのオリジン転送です。「Cloudflare Tunnel」ページで管理してください",
  "系统自动生成的 STUN 打洞转发，请到「STUN」页面管理": "システムが自動生成した STUN ホールパンチング転送です。「STUN」ページで管理してください",
  "系统自动生成的内网穿透转发，请到「代理列表」页面管理": "システムが自動生成したリバーストンネリング転送です。「プロキシ一覧」ページで管理してください",
  "细节改进：密码验证页文案精简；域名模式访问接口地址不再携带端口、统一经 frpc 域名代理；打开密码验证页记录访问日志；系统设置「证书管理」标签精简为 TLS": "細部の改善：パスワード認証ページの文言を簡潔化。ドメインモードの API アドレスはポートを含めず、frpc のドメインプロキシを経由。パスワード認証ページを開いた際にアクセスログを記録。システム設定の「証明書管理」タブを TLS に短縮",
