  "限制IP+端口。只有客户端主动连接过的确切IP和端口组合，才能反向连接。": "IP+ポート制限。クライアントが能動的に接続した正確な IP とポートの組み合わせのみ、逆方向に接続できます",
  "限制IP地址。只有客户端主动连接过的IP地址，才能反向连接客户端（端口不限）。": "IP アドレス制限。クライアントが能動的に接続した IP アドレスのみ、クライアントへ逆方向に接続できます（ポートは不問）",
