  "Cloudflare Tunnel 支持多隧道实例：每条实例独立凭证、内核进程、路由表与日志，可分别启停/重启/删除，内核二进制全局共用；旧单实例配置自动迁移；新增「从云端刷新路由表」把 Cloudflare 后台改动同步回本页。临时入口新增「暂停/恢复」——暂停不断线、不换访问地址（访客看到 503），改本地回源无需重启内核": "Cloudflare Tunnel が複数のトンネルインスタンスに対応：各インスタンスは独自の認証情報、カーネルプロセス、ルーティングテーブル、ログを持ち、個別に起動／停止・再起動・削除が可能です。カーネルのバイナリは全体で共有します。旧単一インスタンス設定は自動的に移行されます。新たに「クラウドからルートを更新」を追加し、Cloudflare 管理画面での変更をこのページに同期できます。一時エントリには「一時停止／再開」を追加しました。一時停止しても接続は切れず、アクセス URL も変わらず（訪問者には 503 が表示されます）、ローカルのオリジン変更にカーネルの再起動は不要です",
