  "ingress 为整份覆盖式配置，本页始终保有该实例的完整路由表，避免清掉你在 Cloudflare 后台手工添加的规则。\n          新增路由会自动补建指向隧道的 CNAME 记录。": "ingress は設定全体を上書きする形式です。このページはこのインスタンスの完全なルートテーブルを常に保持するため、Cloudflare のダッシュボードで手動追加したルールが消えることはありません。\n          ルートを追加すると、トンネルを指す CNAME レコードが自動的に作成されます。",
