  "IP 过滤（拦截）重构升级：新增白名单/黑名单模式（白名单仅放行名单内地址，黑名单默认拦截名单内地址）、局域网地址放行开关（默认开启，关闭前弹出风险提示）、按归属地（国家/省/市/运营商/公有云）直接加入黑白名单、白名单防误锁保护、本机回环固定放行、默认关闭": "IP フィルタリング（ブロック）の刷新：許可/拒否リストモードを追加（許可リストはリスト内のアドレスのみ通過、拒否リストはリスト内のアドレスを既定でブロック）、LAN アドレス許可スイッチ（既定はオン、オフにする前にリスク警告を表示）、IP ジオロケーション（国/省/市/プロバイダー/パブリッククラウド）から直接許可/拒否リストへ追加、許可リストによる誤ロック防止、ローカルループバックは常に許可、既定はオフ",
  "IP 过滤黑名单升级为「自定义内网IP/网段」并全面生效": "IP フィルタリングの拒否リストを「カスタム LAN IP/サブネット」に刷新し、全体で有効化",
