  "IP 模式下的系统地址，留空时自动填入匹配地址：优先公网地址，没有则使用本机局域网地址。": "IP モードのシステムアドレス。空欄の場合は一致するアドレスが自動入力されます。パブリックアドレスを優先し、なければローカルの LAN アドレスを使用します。",
  "IP 模式下生成的访问地址，留空时自动填入匹配地址：优先公网地址，没有则使用本机局域网地址。": "IP モードで生成されるアクセスアドレス。空欄の場合は一致するアドレスが自動入力されます。パブリックアドレスを優先し、なければローカルの LAN アドレスを使用します。",
