  "STUN 打洞": "STUN ホールパンチング",
  "STUN 服务器": "STUN サーバー",
  "STUN 服务器 {0} 格式错误：{1}": "STUN サーバー {0} の形式が正しくありません：{1}",
  "STUN 服务器：": "STUN サーバー：",
  "STUN 服务器列表": "STUN サーバーリスト",
  "STUN 服务器列表用于「STUN 探测」与开启「使用默认 STUN 服务器」的打洞通道；通道关闭该开关后可使用自己的列表，不影响其他通道。保活间隔为打洞通道维持 NAT 映射的周期，保存后立即生效（无需重启）。": "STUN サーバーリストは「STUN 検出」と、「デフォルト STUN サーバーを使用」を有効にしたホールパンチングトンネルで使用されます。トンネルでこのスイッチをオフにすると独自のリストを使用でき、他のトンネルには影響しません。キープアライブ間隔はホールパンチングトンネルが NAT マッピングを維持する周期で、保存後すぐに反映されます（再起動不要）。",
  "STUN 服务器配置移除「名称」字段，仅保留地址与协议，探测/打洞下拉直接显示地址；数据库旧 name 字段在服务启动时自动检测并回写清理，恢复旧备份后重启亦自愈": "STUN サーバー設定から「名前」フィールドを削除し、アドレスとプロトコルのみを保持します。検出/ホールパンチングのドロップダウンにはアドレスを直接表示します。データベースの旧 name フィールドはサービスの起動時に自動検出して書き戻してクリーンアップし、古いバックアップを復元して再起動した場合も自動修復されます",
  "STUN 服务器自动轮换，连续打洞失败达到此次数后通道自动停止（默认 30，范围 1-1000）；收到一次有效响应即重新计数。": "STUN サーバーは自動的に切り替わり、連続してホールパンチングに失敗した回数がこの値に達するとトンネルは自動停止します（既定 30、範囲 1-1000）。有効な応答を 1 回受け取るとカウントはリセットされます。",
  "STUN 设置已保存并生效": "STUN 設定を保存し、反映しました",
