  "Webhook 接收 · 公网地址重定向 / 代理到访问域名": "Webhook 受信 · パブリックアドレスをアクセスドメインへリダイレクト / プロキシ",
  "Webhook 接收（STUN 客户端上报公网地址）与通道访问共用端口，默认 19520；0/80/443 省略端口显示。": "Webhook 受信（STUN クライアントがパブリックアドレスを通知）はトンネルアクセスとポートを共用し、既定は 19520 です。0/80/443 の場合はポートを表示しません。",
  "Webhook 接收自动管理：创建通道后自动开启接收；存在通道时接收始终保持开启（设置页移除开关行，后端拒绝关闭请求），避免用户误关导致通道失效": "Webhook 受信の自動管理：トンネル作成後に受信を自動的に有効化し、トンネルが存在する間は受信を常に有効に保ちます（設定ページのスイッチ行を削除し、バックエンドは無効化リクエストを拒否）。ユーザーが誤ってオフにしてトンネルが使えなくなるのを防ぎます",
  "Webhook 配置": "Webhook 設定",
  "Webhook 通道": "Webhook トンネル",
  "Webhook 通道分组管理增强：删除分组时弹窗选择目标分组移动通道（仅剩 default 分组时自动移入 default）；创建通道后自动展开对应分组；空分组不再显示；分组列表超 5 个启用滚动条，避免撑开页面": "Webhook トンネルのグループ管理を強化：グループ削除時に、トンネルの移動先グループを選択するダイアログを表示（default グループのみ残る場合は自動的に default へ移動）。トンネル作成後に対応するグループを自動展開。空のグループは表示しない。グループが 5 つを超えるとリストにスクロールバーを表示し、ページが伸びるのを防止",
  "Webhook 通道记录": "Webhook トンネル記録",
