  "修复 frpc 日志查看接口带写副作用：LogTailFor 此前会按配置的日志保留行数顺带裁剪日志（即重写整个文件），上一版新增的登录看门狗每 2 秒调用一次，使只读接口变成高频写盘。现将裁剪与读取解耦：LogTailFor 改为纯读，裁剪收敛到新的唯一入口 TrimLogs，由看门狗按 60 秒间隔节流执行，防止日志无限增长的原有能力不变；仅当 LogEntries > 0 时才会触发裁剪，默认 0（不限制）不受影响": "frpc ログ表示 API の書き込み副作用を修正：LogTailFor は設定されたログ保持行数に合わせてログを切り詰めており、ファイル全体を書き換えていました。前バージョンで追加したログイン監視が 2 秒ごとに呼び出すため、読み取り専用 API が高頻度のディスク書き込みになっていました。切り詰めと読み取りを分離し、LogTailFor は純粋な読み取りに、切り詰めは新しい唯一の入口 TrimLogs に集約して、監視ループが 60 秒間隔で実行します。ログが無限に増えないようにする既存の機能は変わりません。切り詰めは LogEntries > 0 の場合のみ実行され、既定値 0（無制限）では影響ありません。",
  "新增 frpc 登录看门狗，穿透断连后能自行恢复：按日志中最后一条登录结果判定，连续 10 次失败（约 20 秒）自动重启该实例并清零计数；进程重启后有 30 秒启动宽限期，避免旧日志残留触发连续重启。判定依据是登录日志而非管理 API——管理 API 只反映 frpc 进程存活，不反映隧道是否连通": "frpc ログイン監視を追加し、トンネル切断後に自動復旧できるようにしました：ログの最後のログイン結果で判定し、10 回連続で失敗（約 20 秒）するとインスタンスを自動再起動してカウントをリセットします。再起動後 30 秒の猶予期間を設け、古いログによる連続再起動を防ぎます。判定は管理 API ではなくログインログに基づきます。管理 API は frpc プロセスの生存を示すだけで、トンネルの接続状態は示さないためです。",
  "FRP 管理 API 查询失败不再静默丢弃：/api/frpc/conns 新增 failed 字段，返回查询失败的服务器及原因（无应答 / HTTP 状态码 / 响应解析失败），界面可区分「隧道断开」与「查不到状态」": "FRP 管理 API の照会失敗を黙って破棄しないようにしました：/api/frpc/conns に failed フィールドを追加し、照会に失敗したサーバーと理由（応答なし / HTTP ステータス / 応答解析失敗）を返します。UI でトンネル切断と状態取得不可を区別できます。",
  "服务器状态新增 watchdog_fails 字段，展示连续登录失败次数，便于确认是否正在自动恢复": "サーバー状態に watchdog_fails フィールドを追加し、連続ログイン失敗回数を表示します。自動復旧が進行中かどうかを確認できます。",
  "搜索更新日志": "更新履歴を検索",
  "没有匹配的版本": "一致するバージョンがありません",
  "管理界面全站国际化：新增简体中文 / 繁体中文 / English / 日本語 四种语言，切换即时生效无需刷新；全部页面、弹窗、表单校验、Toast 与无障碍标签均已接入（3037 条词条）": "管理画面を全面的に多言語化：簡体字中国語・繁体字中国語・英語・日本語の 4 言語に対応し、再読み込みなしで即時切り替えできます。全ページ、ダイアログ、フォーム検証、トースト、アクセシビリティラベルを網羅（3037 件）",
  "「关于」页更新日志支持版本目录与搜索：左侧版本列表可点击跳转并高亮当前版本，搜索框按版本号或条目内容过滤并高亮命中文字": "「このアプリについて」の更新履歴にバージョン索引と検索を追加：左の一覧からジャンプして現在のバージョンを強調表示し、バージョン番号や本文で絞り込み、一致箇所をハイライトします",
  "「关于」页新增「支持开发者」入口，点击弹出赞赏码；免责声明与开发者信息卡片等高，声明正文内部滚动且隐藏滚动条": "「このアプリについて」に開発者支援（応援コード）入口を追加しました。免責事項と開発者情報カードの高さを揃え、免責事項は内部スクロール、スクロールバーは非表示にしました",
  "项目链接更新：项目主页改为 https://tunhook.top，联系方式与开源地址指向 https://github.com/YUNXI-fi/TunHook": "プロジェクトリンクを更新：プロジェクトホームページは https://tunhook.top、連絡先とソースは https://github.com/YUNXI-fi/TunHook を指します",
  "版本号统一为 0.6.6.172（CLI、Web 状态、备份清单、UserAgent、前端包与安装包）": "バージョンを 0.6.6.172 に統一しました（CLI、Web ステータス、バックアップマニフェスト、UserAgent、フロントエンドパッケージ、インストールパッケージ）"
